func TestB10RequestBodyWarnsWithoutRemove(t *testing.T) {
	warned := newWarnings()
	log.SetOutput(warned)
	defer log.SetOutput(os.Stderr)
	gone := func() weak.Pointer[RequestBody] {
		made0, failure1 := RequestBodyStart(ptr("multipart/form-data; boundary=XyZ"), nil, true, BodyLimits{Limit: 1000, ValueLimit: 1000, PartLimit: 10, FileLimit: 1000})
		if failure1 != nil {
			t.Fatalf("GN-13f: %v", failure1)
		}
		return weak.Make(made0)
	}()
	runtime.GC()
	if gone.Value() != nil {
		t.Fatalf("B-10: the collection left the object, so its cleanup does not run")
	}
	warned.await("RequestBody was destroyed without Remove(), so its destructor released it (B-10)")
}
